INSERT INTO vacancies (id, company_id, title, description, location, tags, contact_name, contact_email, created_at) VALUES
(1, 1, 'PHP Developer', 'Als PHP Developer bij Bitwerk Software bouw je mee aan onze webapplicaties en API''s. Je schrijft onderhoudbare PHP-code, ontwerpt MySQL-databases en denkt mee over architectuur. Je werkt in een klein team met korte lijnen en doet mee aan code reviews.\n\nWij bieden een marktconform salaris, een reiskostenvergoeding en ruimte voor opleidingen.', 'Utrecht', 'php,mysql,backend,webdevelopment,api', 'Sanne de Graaf', 'sanne.degraaf@bitwerksoftware.example', '2026-09-23 03:00:00'),
(2, 1, 'Frontend Developer', 'Je vertaalt ontwerpen naar snelle, toegankelijke interfaces in HTML, CSS en JavaScript. Samen met de backend-developers van Bitwerk Software zorg je voor een soepele gebruikerservaring. Kennis van responsive design en browser-compatibiliteit is een must.\n\nWij bieden een contract voor 32 tot 40 uur, flexibele werktijden en een informele werksfeer.', 'Utrecht', 'javascript,html,css,frontend,webdevelopment', 'Sanne de Graaf', 'sanne.degraaf@bitwerksoftware.example', '2026-09-21 14:00:00'),
(3, 1, 'Full Stack Developer', 'Bij Bitwerk Software werk je zowel aan de voorkant als de achterkant van onze producten. Van databaseontwerp tot gebruikersinterface: jij pakt features van begin tot eind op. Je hebt ervaring met PHP, JavaScript en relationele databases.\n\nWij bieden een jaarcontract met uitzicht op vast, een eindejaarsuitkering en een fijn team.', 'Utrecht', 'php,javascript,mysql,fullstack,webdevelopment', 'Sanne de Graaf', 'sanne.degraaf@bitwerksoftware.example', '2026-09-20 01:00:00'),
(4, 1, 'Product Owner', 'Als Product Owner beheer je de backlog en vertaal je wensen van klanten naar duidelijke user stories. Je werkt nauw samen met het ontwikkelteam van Bitwerk Software en bewaakt de prioriteiten. Ervaring met Scrum is een pré.\n\nWij bieden een parttime of fulltime dienstverband, een fiets van de zaak en gezellige teamuitjes.', 'Utrecht', 'scrum,agile,product,stakeholders,ict', 'Sanne de Graaf', 'sanne.degraaf@bitwerksoftware.example', '2026-09-18 12:00:00'),
(5, 2, 'Verpleegkundige niveau 4', 'Als Verpleegkundige verleen je professionele zorg aan cliënten van Noordlicht Zorggroep. Je voert verpleegtechnische handelingen uit, stelt zorgplannen op en bent aanspreekpunt voor collega''s en familie. Een geldige BIG-registratie is vereist.\n\nWij bieden een salaris conform cao, 25 vakantiedagen en een goede pensioenregeling.', 'Groningen', 'zorg,verpleegkunde,big,ouderenzorg', 'Marieke Hoekstra', 'marieke.hoekstra@noordlichtzorggroep.example', '2026-09-16 23:00:00'),
(6, 2, 'Verzorgende IG', 'Je ondersteunt cliënten bij hun dagelijkse verzorging en voert voorbehouden handelingen uit. Bij Noordlicht Zorggroep staat persoonlijke aandacht centraal. Je hebt een diploma Verzorgende IG en werkt graag in een hecht team.\n\nWij bieden een marktconform salaris, een reiskostenvergoeding en ruimte voor opleidingen.', 'Assen', 'zorg,verzorging,ouderenzorg,mbo', 'Marieke Hoekstra', 'marieke.hoekstra@noordlichtzorggroep.example', '2026-09-15 10:00:00'),
(7, 2, 'Helpende Zorg & Welzijn', 'Je helpt cliënten met huishoudelijke taken, maaltijden en dagbesteding. Je zorgt voor een prettige en veilige leefomgeving en signaleert veranderingen bij cliënten van Noordlicht Zorggroep. Een mbo-diploma niveau 2 is gewenst.\n\nWij bieden een contract voor 32 tot 40 uur, flexibele werktijden en een informele werksfeer.', 'Groningen', 'zorg,welzijn,ouderenzorg,mbo', 'Marieke Hoekstra', 'marieke.hoekstra@noordlichtzorggroep.example', '2026-09-13 21:00:00'),
(8, 2, 'Zorgplanner', 'Als Zorgplanner stel je de roosters op voor onze zorgteams en zorg je dat iedere cliënt op tijd de juiste zorg krijgt. Je schakelt snel bij ziekte of spoed en werkt nauw samen met de teamleiders van Noordlicht Zorggroep.\n\nWij bieden een jaarcontract met uitzicht op vast, een eindejaarsuitkering en een fijn team.', 'Groningen', 'planning,zorg,roosters,administratie', 'Marieke Hoekstra', 'marieke.hoekstra@noordlichtzorggroep.example', '2026-09-12 08:00:00'),
(9, 3, 'Timmerman', 'Je werkt mee aan nieuwbouw- en renovatieprojecten in de regio. Van kozijnen plaatsen tot dakconstructies: jij levert vakwerk af. De Vries Bouw & Installatie biedt een vast team, goed gereedschap en doorgroeimogelijkheden.\n\nWij bieden een parttime of fulltime dienstverband, een fiets van de zaak en gezellige teamuitjes.', 'Zwolle', 'bouw,timmeren,nieuwbouw,vakmanschap', 'Henk de Vries', 'henk.devries@devriesbouweninstallatie.example', '2026-09-10 19:00:00'),
(10, 3, 'Uitvoerder Bouw', 'Als Uitvoerder ben je de spil op de bouwplaats. Je stuurt vakmensen en onderaannemers aan, bewaakt planning, kwaliteit en veiligheid en rapporteert aan de projectleider van De Vries Bouw & Installatie. Je hebt minimaal mbo-4 Bouwkunde.\n\nWij bieden een salaris conform cao, 25 vakantiedagen en een goede pensioenregeling.', 'Deventer', 'bouw,uitvoering,projecten,leidinggeven', 'Henk de Vries', 'henk.devries@devriesbouweninstallatie.example', '2026-09-09 06:00:00'),
(11, 3, 'Werkvoorbereider', 'Je bereidt projecten voor: je maakt tekeningen, bestelt materialen en stelt planningen op. Zo zorg je dat de monteurs en bouwers van De Vries Bouw & Installatie zonder vertraging aan de slag kunnen. Je bent nauwkeurig en communicatief sterk.\n\nWij bieden een marktconform salaris, een reiskostenvergoeding en ruimte voor opleidingen.', 'Zwolle', 'werkvoorbereiding,calculatie,projecten,installatie', 'Henk de Vries', 'henk.devries@devriesbouweninstallatie.example', '2026-09-07 17:00:00'),
(12, 3, 'Elektromonteur', 'Je legt elektrische installaties aan in woningen en bedrijfspanden en voert onderhoud en storingsdiensten uit. Bij De Vries Bouw & Installatie werk je met moderne technieken zoals domotica en laadpalen. Een mbo-diploma Elektrotechniek is gewenst.\n\nWij bieden een contract voor 32 tot 40 uur, flexibele werktijden en een informele werksfeer.', 'Zwolle', 'elektrotechniek,installatie,monteur,mbo', 'Henk de Vries', 'henk.devries@devriesbouweninstallatie.example', '2026-09-06 04:00:00'),
(13, 4, 'Orderpicker', 'In ons distributiecentrum verzamel je orders met een handscanner en maak je ze klaar voor verzending. Bij Havenstad Logistiek werk je in een dynamische omgeving met een goede sfeer. Werkervaring is niet vereist, je wordt ingewerkt.\n\nWij bieden een jaarcontract met uitzicht op vast, een eindejaarsuitkering en een fijn team.', 'Rotterdam', 'logistiek,magazijn,orderpicking,fulltime', 'Kees van Dijk', 'kees.vandijk@havenstadlogistiek.example', '2026-09-04 15:00:00'),
(14, 4, 'Heftruckchauffeur', 'Je laadt en lost vrachtwagens, verplaatst pallets en houdt de voorraad op orde. Een heftruckcertificaat is vereist. Havenstad Logistiek biedt een vast contract bij goed functioneren.\n\nWij bieden een parttime of fulltime dienstverband, een fiets van de zaak en gezellige teamuitjes.', 'Schiedam', 'logistiek,heftruck,magazijn,laden-lossen', 'Kees van Dijk', 'kees.vandijk@havenstadlogistiek.example', '2026-09-03 02:00:00'),
(15, 4, 'Teamleider Magazijn', 'Je stuurt een team van 15 magazijnmedewerkers aan en zorgt dat orders op tijd en foutloos de deur uit gaan. Je signaleert verbeterpunten en coacht je team. Ervaring als leidinggevende in de logistiek bij voorkeur.\n\nWij bieden een salaris conform cao, 25 vakantiedagen en een goede pensioenregeling.', 'Rotterdam', 'logistiek,magazijn,leidinggeven,planning', 'Kees van Dijk', 'kees.vandijk@havenstadlogistiek.example', '2026-09-01 13:00:00'),
(16, 4, 'Transportplanner', 'Als Transportplanner plan je dagelijks de ritten van onze chauffeurs zo efficiënt mogelijk. Je houdt contact met klanten en chauffeurs en lost onverwachte situaties snel op. Bij Havenstad Logistiek werk je met moderne planningssoftware.\n\nWij bieden een marktconform salaris, een reiskostenvergoeding en ruimte voor opleidingen.', 'Rotterdam', 'planning,transport,logistiek,klantcontact', 'Kees van Dijk', 'kees.vandijk@havenstadlogistiek.example', '2026-08-31 00:00:00'),
(17, 5, 'Hovenier', 'Je legt tuinen aan en onderhoudt ze voor particuliere en zakelijke klanten. Bestrating, beplanting en snoeiwerk: jij doet het allemaal. Bij Groenhart Hoveniers werk je buiten in een gezellig team.\n\nWij bieden een contract voor 32 tot 40 uur, flexibele werktijden en een informele werksfeer.', 'Arnhem', 'groen,hovenier,tuinaanleg,buitenwerk', 'Lotte Vermeulen', 'lotte.vermeulen@groenharthoveniers.example', '2026-08-29 11:00:00'),
(18, 5, 'Medewerker Groenvoorziening', 'Je onderhoudt parken, bermen en terreinen: maaien, snoeien en onkruid bestrijden. Je werkt met professioneel materieel van Groenhart Hoveniers. Een trekkerrijbewijs is een pré.\n\nWij bieden een jaarcontract met uitzicht op vast, een eindejaarsuitkering en een fijn team.', 'Ede', 'groen,onderhoud,buitenwerk,maaien', 'Lotte Vermeulen', 'lotte.vermeulen@groenharthoveniers.example', '2026-08-27 22:00:00'),
(19, 5, 'Tuinontwerper', 'Je ontwerpt tuinen die passen bij de wensen van de klant. Je maakt schetsen en 3D-tekeningen, stelt beplantingsplannen op en begeleidt de aanleg samen met de hoveniers van Groenhart Hoveniers.\n\nWij bieden een parttime of fulltime dienstverband, een fiets van de zaak en gezellige teamuitjes.', 'Arnhem', 'ontwerp,tuinarchitectuur,groen,creatief', 'Lotte Vermeulen', 'lotte.vermeulen@groenharthoveniers.example', '2026-08-26 09:00:00'),
(20, 5, 'Officemanager', 'Je houdt het kantoor draaiende: agendabeheer, inkoop, administratie en de ontvangst van gasten. Je bent de spin in het web bij Groenhart Hoveniers en houdt van structuur.\n\nWij bieden een salaris conform cao, 25 vakantiedagen en een goede pensioenregeling.', 'Arnhem', 'administratie,secretariaat,organisatie,office', 'Lotte Vermeulen', 'lotte.vermeulen@groenharthoveniers.example', '2026-08-24 20:00:00'),
(21, 6, 'Online Marketeer', 'Je bedenkt en voert online campagnes uit via SEO, SEA en social media. Met data uit analytics optimaliseer je de resultaten continu. Bij Pixelpoort Media krijg je de ruimte om te experimenteren.\n\nWij bieden een marktconform salaris, een reiskostenvergoeding en ruimte voor opleidingen.', 'Amsterdam', 'marketing,seo,sea,social-media,analytics', 'Yara El Idrissi', 'yara.elidrissi@pixelpoortmedia.example', '2026-08-23 07:00:00'),
(22, 6, 'Content Creator', 'Je maakt pakkende content voor social media en websites: video, fotografie en korte teksten. Je volgt trends op de voet en weet wat werkt bij de doelgroep van Pixelpoort Media.\n\nWij bieden een contract voor 32 tot 40 uur, flexibele werktijden en een informele werksfeer.', 'Amsterdam', 'content,video,social-media,marketing,creatief', 'Yara El Idrissi', 'yara.elidrissi@pixelpoortmedia.example', '2026-08-21 18:00:00'),
(23, 6, 'Grafisch Vormgever', 'Je ontwerpt huisstijlen, advertenties en publicaties, zowel voor print als online. Je werkt met Adobe InDesign, Illustrator en Photoshop en brengt de visuele identiteit van Pixelpoort Media en haar klanten tot leven.\n\nWij bieden een jaarcontract met uitzicht op vast, een eindejaarsuitkering en een fijn team.', 'Amsterdam', 'vormgeving,design,adobe,creatief,drukwerk', 'Yara El Idrissi', 'yara.elidrissi@pixelpoortmedia.example', '2026-08-20 05:00:00'),
(24, 6, 'Accountmanager', 'Je onderhoudt en versterkt de relatie met bestaande klanten en zoekt actief naar nieuwe kansen. Je bent het gezicht van Pixelpoort Media en weet klantwensen te vertalen naar passende oplossingen.\n\nWij bieden een parttime of fulltime dienstverband, een fiets van de zaak en gezellige teamuitjes.', 'Amsterdam', 'sales,accountmanagement,commercieel,b2b', 'Yara El Idrissi', 'yara.elidrissi@pixelpoortmedia.example', '2026-08-18 16:00:00'),
(25, 7, 'Kok', 'Je bereidt gerechten volgens onze kaart met verse, lokale ingrediënten. Je werkt mee aan nieuwe menu''s en houdt de keuken schoon en georganiseerd. Kustlijn Hotels zoekt iemand met passie voor koken.\n\nWij bieden een salaris conform cao, 25 vakantiedagen en een goede pensioenregeling.', 'Noordwijk', 'horeca,keuken,koken,fulltime', 'Thomas Bakker', 'thomas.bakker@kustlijnhotels.example', '2026-08-17 03:00:00'),
(26, 7, 'Receptionist', 'Je ontvangt gasten, handelt check-ins en reserveringen af en beantwoordt vragen. Je bent het visitekaartje van Kustlijn Hotels. Je spreekt vloeiend Nederlands en Engels, Duits is een pré.\n\nWij bieden een marktconform salaris, een reiskostenvergoeding en ruimte voor opleidingen.', 'Den Haag', 'hospitality,receptie,gastvrijheid,talen', 'Thomas Bakker', 'thomas.bakker@kustlijnhotels.example', '2026-08-15 14:00:00'),
(27, 7, 'Medewerker Bediening', 'Je zorgt dat gasten zich welkom voelen in ons restaurant. Je neemt bestellingen op, serveert gerechten en geeft advies over wijn. Bij Kustlijn Hotels werk je in wisselende diensten, ook in het weekend.\n\nWij bieden een contract voor 32 tot 40 uur, flexibele werktijden en een informele werksfeer.', 'Den Haag', 'horeca,bediening,gastvrijheid,bijbaan', 'Thomas Bakker', 'thomas.bakker@kustlijnhotels.example', '2026-08-14 01:00:00'),
(28, 7, 'Medewerker Housekeeping', 'Je maakt kamers en accommodaties schoon en zorgt dat alles tot in de puntjes verzorgd is voor nieuwe gasten. Bij Kustlijn Hotels werk je in een hecht team met flexibele uren.\n\nWij bieden een jaarcontract met uitzicht op vast, een eindejaarsuitkering en een fijn team.', 'Den Haag', 'schoonmaak,housekeeping,hotel,parttime', 'Thomas Bakker', 'thomas.bakker@kustlijnhotels.example', '2026-08-12 12:00:00'),
(29, 8, 'Werktuigbouwkundig Engineer', 'Je ontwerpt en verbetert machines en onderdelen met behulp van CAD-software. Je werkt van concept tot prototype en overlegt met productie en klanten van Brabant Techniek. Je hebt een hbo-opleiding Werktuigbouwkunde.\n\nWij bieden een parttime of fulltime dienstverband, een fiets van de zaak en gezellige teamuitjes.', 'Eindhoven', 'engineering,werktuigbouw,cad,techniek,hbo', 'Ruud Jansen', 'ruud.jansen@brabanttechniek.example', '2026-08-10 23:00:00'),
(30, 8, 'Onderhoudsmonteur', 'Je voert preventief en correctief onderhoud uit aan productie-installaties. Je spoort storingen op en lost ze snel op om stilstand bij Brabant Techniek te beperken. Kennis van mechanica en elektrotechniek is vereist.\n\nWij bieden een salaris conform cao, 25 vakantiedagen en een goede pensioenregeling.', 'Eindhoven', 'onderhoud,mechanica,elektrotechniek,storingen', 'Ruud Jansen', 'ruud.jansen@brabanttechniek.example', '2026-08-09 10:00:00'),
(31, 8, 'Operator', 'Je bedient en stelt productiemachines in, lost kleine storingen op en bewaakt de kwaliteit van het eindproduct. Bij Brabant Techniek werk je in ploegendienst. Een technische mbo-opleiding is gewenst.\n\nWij bieden een marktconform salaris, een reiskostenvergoeding en ruimte voor opleidingen.', 'Helmond', 'productie,machine,techniek,ploegendienst', 'Ruud Jansen', 'ruud.jansen@brabanttechniek.example', '2026-08-07 21:00:00'),
(32, 8, 'Kwaliteitsmedewerker', 'Je controleert producten en processen, analyseert afwijkingen en stelt verbetervoorstellen op. Je helpt Brabant Techniek bij het behouden van ISO-certificeringen. Je bent nauwkeurig en analytisch.\n\nWij bieden een contract voor 32 tot 40 uur, flexibele werktijden en een informele werksfeer.', 'Eindhoven', 'kwaliteit,iso,controle,productie', 'Ruud Jansen', 'ruud.jansen@brabanttechniek.example', '2026-08-06 08:00:00'),
(33, 9, 'Productiemedewerker', 'Je assembleert producten aan de productielijn en controleert de kwaliteit. Je werkt in een 2-ploegendienst bij Fietsfabriek Oost. Technische ervaring is niet vereist, wel een goede werkhouding.\n\nWij bieden een jaarcontract met uitzicht op vast, een eindejaarsuitkering en een fijn team.', 'Enschede', 'productie,assemblage,fabriek,ploegendienst', 'Anouk Nijhuis', 'anouk.nijhuis@fietsfabriekoost.example', '2026-08-04 19:00:00'),
(34, 9, 'Operator', 'Je bedient en stelt productiemachines in, lost kleine storingen op en bewaakt de kwaliteit van het eindproduct. Bij Fietsfabriek Oost werk je in ploegendienst. Een technische mbo-opleiding is gewenst.\n\nWij bieden een parttime of fulltime dienstverband, een fiets van de zaak en gezellige teamuitjes.', 'Enschede', 'productie,machine,techniek,ploegendienst', 'Anouk Nijhuis', 'anouk.nijhuis@fietsfabriekoost.example', '2026-08-03 06:00:00'),
(35, 9, 'Kwaliteitsmedewerker', 'Je controleert producten en processen, analyseert afwijkingen en stelt verbetervoorstellen op. Je helpt Fietsfabriek Oost bij het behouden van ISO-certificeringen. Je bent nauwkeurig en analytisch.\n\nWij bieden een salaris conform cao, 25 vakantiedagen en een goede pensioenregeling.', 'Enschede', 'kwaliteit,iso,controle,productie', 'Anouk Nijhuis', 'anouk.nijhuis@fietsfabriekoost.example', '2026-08-01 17:00:00'),
(36, 9, 'Klantenservicemedewerker', 'Je beantwoordt vragen van klanten via telefoon, e-mail en chat. Je lost problemen op en zorgt dat klanten van Fietsfabriek Oost tevreden zijn. Je bent geduldig en schrijft foutloos Nederlands.\n\nWij bieden een marktconform salaris, een reiskostenvergoeding en ruimte voor opleidingen.', 'Enschede', 'klantenservice,klantcontact,telefoon,parttime', 'Anouk Nijhuis', 'anouk.nijhuis@fietsfabriekoost.example', '2026-07-31 04:00:00'),
(37, 10, 'Assistent Accountant', 'Je stelt jaarrekeningen en belastingaangiften op voor mkb-klanten. Je bent een vast aanspreekpunt voor klanten van Zuiderzee Accountants en krijgt de kans om je verder te ontwikkelen via een opleiding.\n\nWij bieden een contract voor 32 tot 40 uur, flexibele werktijden en een informele werksfeer.', 'Almere', 'accountancy,boekhouden,jaarrekening,finance', 'Pieter Smit', 'pieter.smit@zuiderzeeaccountants.example', '2026-07-29 15:00:00'),
(38, 10, 'Financieel Administratief Medewerker', 'Je verwerkt inkoop- en verkoopfacturen, doet bankmutaties en ondersteunt bij maand- en jaarafsluitingen. Bij Zuiderzee Accountants werk je met Exact Online. Een mbo-4 opleiding in financiële richting is gewenst.\n\nWij bieden een jaarcontract met uitzicht op vast, een eindejaarsuitkering en een fijn team.', 'Almere', 'administratie,boekhouden,finance,exact', 'Pieter Smit', 'pieter.smit@zuiderzeeaccountants.example', '2026-07-28 02:00:00'),
(39, 10, 'Salarisadministrateur', 'Je verzorgt de salarisadministratie voor diverse klanten van Zuiderzee Accountants. Je verwerkt mutaties, maakt loonstroken en beantwoordt vragen over arbeidsvoorwaarden en loonheffing.\n\nWij bieden een parttime of fulltime dienstverband, een fiets van de zaak en gezellige teamuitjes.', 'Lelystad', 'salarisadministratie,payroll,hr,loonheffing', 'Pieter Smit', 'pieter.smit@zuiderzeeaccountants.example', '2026-09-24 13:00:00'),
(40, 10, 'Controller', 'Je bewaakt de financiële gezondheid van de organisatie, stelt begrotingen en managementrapportages op en adviseert de directie van Zuiderzee Accountants. Je hebt een hbo- of wo-opleiding in financiële richting.\n\nWij bieden een salaris conform cao, 25 vakantiedagen en een goede pensioenregeling.', 'Almere', 'finance,controlling,rapportage,hbo', 'Pieter Smit', 'pieter.smit@zuiderzeeaccountants.example', '2026-09-23 00:00:00'),
(41, 11, 'Vrachtwagenchauffeur CE', 'Je vervoert goederen van en naar klanten in de Benelux en Duitsland. Je rijdt in een modern wagenpark van Dijkstra Transport en bent elke avond of een paar keer per week thuis. Rijbewijs CE, code 95 en een digitale tachograafkaart zijn vereist.\n\nWij bieden een marktconform salaris, een reiskostenvergoeding en ruimte voor opleidingen.', 'Leeuwarden', 'chauffeur,transport,rijbewijs-ce,logistiek', 'Jelle Dijkstra', 'jelle.dijkstra@dijkstratransport.example', '2026-09-21 11:00:00'),
(42, 11, 'Transportplanner', 'Als Transportplanner plan je dagelijks de ritten van onze chauffeurs zo efficiënt mogelijk. Je houdt contact met klanten en chauffeurs en lost onverwachte situaties snel op. Bij Dijkstra Transport werk je met moderne planningssoftware.\n\nWij bieden een contract voor 32 tot 40 uur, flexibele werktijden en een informele werksfeer.', 'Leeuwarden', 'planning,transport,logistiek,klantcontact', 'Jelle Dijkstra', 'jelle.dijkstra@dijkstratransport.example', '2026-09-19 22:00:00'),
(43, 11, 'Orderpicker', 'In ons distributiecentrum verzamel je orders met een handscanner en maak je ze klaar voor verzending. Bij Dijkstra Transport werk je in een dynamische omgeving met een goede sfeer. Werkervaring is niet vereist, je wordt ingewerkt.\n\nWij bieden een jaarcontract met uitzicht op vast, een eindejaarsuitkering en een fijn team.', 'Drachten', 'logistiek,magazijn,orderpicking,fulltime', 'Jelle Dijkstra', 'jelle.dijkstra@dijkstratransport.example', '2026-09-18 09:00:00'),
(44, 11, 'Heftruckchauffeur', 'Je laadt en lost vrachtwagens, verplaatst pallets en houdt de voorraad op orde. Een heftruckcertificaat is vereist. Dijkstra Transport biedt een vast contract bij goed functioneren.\n\nWij bieden een parttime of fulltime dienstverband, een fiets van de zaak en gezellige teamuitjes.', 'Leeuwarden', 'logistiek,heftruck,magazijn,laden-lossen', 'Jelle Dijkstra', 'jelle.dijkstra@dijkstratransport.example', '2026-09-16 20:00:00'),
(45, 12, 'Bakker', 'Je bakt dagelijks vers brood, banket en gebak volgens ambachtelijke recepten. Je begint vroeg, maar bent ook vroeg klaar. Stadsbakkerij Meijer zoekt iemand met liefde voor het vak.\n\nWij bieden een salaris conform cao, 25 vakantiedagen en een goede pensioenregeling.', 'Haarlem', 'bakkerij,brood,ambacht,vroege-diensten', 'Ingrid Meijer', 'ingrid.meijer@stadsbakkerijmeijer.example', '2026-09-15 07:00:00'),
(46, 12, 'Verkoopmedewerker', 'Je helpt klanten in de winkel, geeft advies en rekent af aan de kassa. Je zorgt dat de winkel van Stadsbakkerij Meijer er altijd verzorgd uitziet. Je bent klantvriendelijk en flexibel inzetbaar.\n\nWij bieden een marktconform salaris, een reiskostenvergoeding en ruimte voor opleidingen.', 'Haarlem', 'retail,verkoop,klantcontact,winkel', 'Ingrid Meijer', 'ingrid.meijer@stadsbakkerijmeijer.example', '2026-09-13 18:00:00'),
(47, 12, 'Filiaalmanager', 'Je bent eindverantwoordelijk voor het filiaal: omzet, personeel en presentatie. Je motiveert je team en zorgt voor een uitstekende klantbeleving bij Stadsbakkerij Meijer. Ervaring als leidinggevende in retail is vereist.\n\nWij bieden een contract voor 32 tot 40 uur, flexibele werktijden en een informele werksfeer.', 'Heemstede', 'retail,leidinggeven,management,winkel', 'Ingrid Meijer', 'ingrid.meijer@stadsbakkerijmeijer.example', '2026-09-12 05:00:00'),
(48, 12, 'Bezorger', 'Je bezorgt bestellingen bij particulieren en bedrijven in de regio met een bestelbus van Stadsbakkerij Meijer. Je bent punctueel, vriendelijk en hebt rijbewijs B.\n\nWij bieden een jaarcontract met uitzicht op vast, een eindejaarsuitkering en een fijn team.', 'Haarlem', 'bezorging,rijbewijs-b,bijbaan,klantcontact', 'Ingrid Meijer', 'ingrid.meijer@stadsbakkerijmeijer.example', '2026-09-10 16:00:00'),
(49, 13, 'DevOps Engineer', 'Je automatiseert deployments, beheert CI/CD-pipelines en zorgt dat onze cloudomgeving stabiel en schaalbaar blijft. Bij CloudNest Hosting werk je met Linux, Docker en infrastructure as code. Je denkt proactief mee over monitoring en beschikbaarheid.\n\nWij bieden een parttime of fulltime dienstverband, een fiets van de zaak en gezellige teamuitjes.', 'Amsterdam', 'devops,linux,docker,cloud,ci-cd', 'Daan Koster', 'daan.koster@cloudnesthosting.example', '2026-09-09 03:00:00'),
(50, 13, 'Systeembeheerder', 'Als Systeembeheerder ben je verantwoordelijk voor servers, netwerken en werkplekken. Je lost storingen op, voert updates door en adviseert over verbeteringen in de IT-omgeving van CloudNest Hosting. Je hebt kennis van zowel Linux als Windows.\n\nWij bieden een salaris conform cao, 25 vakantiedagen en een goede pensioenregeling.', 'Amsterdam', 'systeembeheer,linux,windows,netwerk,ict', 'Daan Koster', 'daan.koster@cloudnesthosting.example', '2026-09-07 14:00:00'),
(51, 13, 'Servicedesk Medewerker', 'Je bent het eerste aanspreekpunt voor klanten met technische vragen. Via telefoon, mail en chat help je gebruikers van CloudNest Hosting snel verder. Je registreert meldingen zorgvuldig en schaalt complexe issues op naar de tweede lijn.\n\nWij bieden een marktconform salaris, een reiskostenvergoeding en ruimte voor opleidingen.', 'Amsterdam', 'servicedesk,ict,support,klantcontact', 'Daan Koster', 'daan.koster@cloudnesthosting.example', '2026-09-06 01:00:00'),
(52, 13, 'PHP Developer', 'Als PHP Developer bij CloudNest Hosting bouw je mee aan onze webapplicaties en API''s. Je schrijft onderhoudbare PHP-code, ontwerpt MySQL-databases en denkt mee over architectuur. Je werkt in een klein team met korte lijnen en doet mee aan code reviews.\n\nWij bieden een contract voor 32 tot 40 uur, flexibele werktijden en een informele werksfeer.', 'Amsterdam', 'php,mysql,backend,webdevelopment,api', 'Daan Koster', 'daan.koster@cloudnesthosting.example', '2026-09-04 12:00:00'),
(53, 14, 'Pedagogisch Medewerker', 'Je begeleidt kinderen van 0 tot 4 jaar op het kinderdagverblijf en zorgt voor een veilige, stimulerende omgeving. Je hebt contact met ouders en observeert de ontwikkeling van kinderen bij Rivierenland Kinderopvang.\n\nWij bieden een jaarcontract met uitzicht op vast, een eindejaarsuitkering en een fijn team.', 'Nijmegen', 'kinderopvang,pedagogiek,kinderen,mbo', 'Fleur Willems', 'fleur.willems@rivierenlandkinderopvang.example', '2026-09-02 23:00:00'),
(54, 14, 'Pedagogisch Medewerker BSO', 'Na schooltijd organiseer je leuke activiteiten voor kinderen van 4 tot 12 jaar: sport, spel en creativiteit. Je werkt op de buitenschoolse opvang van Rivierenland Kinderopvang. Een passend pedagogisch diploma is vereist.\n\nWij bieden een parttime of fulltime dienstverband, een fiets van de zaak en gezellige teamuitjes.', 'Tiel', 'kinderopvang,bso,sport,kinderen', 'Fleur Willems', 'fleur.willems@rivierenlandkinderopvang.example', '2026-09-01 10:00:00'),
(55, 14, 'Locatiemanager Kinderopvang', 'Je geeft leiding aan het team van een kinderopvanglocatie en bent verantwoordelijk voor kwaliteit, bezetting en oudercontact. Je vertaalt het beleid van Rivierenland Kinderopvang naar de dagelijkse praktijk.\n\nWij bieden een salaris conform cao, 25 vakantiedagen en een goede pensioenregeling.', 'Nijmegen', 'kinderopvang,leidinggeven,management,hbo', 'Fleur Willems', 'fleur.willems@rivierenlandkinderopvang.example', '2026-08-30 21:00:00'),
(56, 14, 'Recruiter', 'Je vindt en werft nieuwe collega''s voor Rivierenland Kinderopvang. Je schrijft vacatureteksten, benadert kandidaten actief en voert selectiegesprekken. Je kent de arbeidsmarkt en bent een echte netwerker.\n\nWij bieden een marktconform salaris, een reiskostenvergoeding en ruimte voor opleidingen.', 'Nijmegen', 'recruitment,hr,werving,arbeidsmarkt', 'Fleur Willems', 'fleur.willems@rivierenlandkinderopvang.example', '2026-08-29 08:00:00'),
(57, 15, 'Monteur Zonnepanelen', 'Je installeert zonnepanelen en omvormers op daken van woningen en bedrijven. Je werkt in een team van twee en draagt bij aan de energietransitie met Maasstad Energie. Hoogtevrees heb je niet.\n\nWij bieden een contract voor 32 tot 40 uur, flexibele werktijden en een informele werksfeer.', 'Dordrecht', 'zonnepanelen,duurzaam,installatie,energie', 'Mohammed Amrani', 'mohammed.amrani@maasstadenergie.example', '2026-08-27 19:00:00'),
(58, 15, 'Energieadviseur', 'Je adviseert huiseigenaren en bedrijven over energiebesparing, isolatie en duurzame installaties. Je maakt energielabels en offertes namens Maasstad Energie. Je bent communicatief sterk en technisch onderlegd.\n\nWij bieden een jaarcontract met uitzicht op vast, een eindejaarsuitkering en een fijn team.', 'Rotterdam', 'energie,advies,duurzaam,klantcontact', 'Mohammed Amrani', 'mohammed.amrani@maasstadenergie.example', '2026-08-26 06:00:00'),
(59, 15, 'Projectleider Energietransitie', 'Je leidt projecten op het gebied van warmtenetten en duurzame opwek, van haalbaarheidsstudie tot oplevering. Je stuurt partners aan en bewaakt budget en planning voor Maasstad Energie.\n\nWij bieden een parttime of fulltime dienstverband, een fiets van de zaak en gezellige teamuitjes.', 'Rotterdam', 'energie,projectmanagement,duurzaam,hbo', 'Mohammed Amrani', 'mohammed.amrani@maasstadenergie.example', '2026-08-24 17:00:00'),
(60, 15, 'Monteur Middenspanning', 'Je legt kabelverbindingen aan en voert onderhoud uit aan middenspanningsstations. Veiligheid staat voorop bij Maasstad Energie. Je hebt een mbo-diploma Elektrotechniek en VCA.\n\nWij bieden een salaris conform cao, 25 vakantiedagen en een goede pensioenregeling.', 'Rotterdam', 'elektrotechniek,energie,netwerk,monteur', 'Mohammed Amrani', 'mohammed.amrani@maasstadenergie.example', '2026-08-23 04:00:00'),
(61, 16, 'Recreatiemedewerker', 'Je organiseert activiteiten voor jong en oud op ons vakantiepark. Van kinderdisco tot speurtochten: jij zorgt voor een onvergetelijke vakantie bij Veluwe Vakantieparken. Je bent enthousiast en flexibel.\n\nWij bieden een marktconform salaris, een reiskostenvergoeding en ruimte voor opleidingen.', 'Apeldoorn', 'recreatie,animatie,toerisme,kinderen', 'Bas Hendriks', 'bas.hendriks@veluwevakantieparken.example', '2026-08-21 15:00:00'),
(62, 16, 'Receptionist', 'Je ontvangt gasten, handelt check-ins en reserveringen af en beantwoordt vragen. Je bent het visitekaartje van Veluwe Vakantieparken. Je spreekt vloeiend Nederlands en Engels, Duits is een pré.\n\nWij bieden een contract voor 32 tot 40 uur, flexibele werktijden en een informele werksfeer.', 'Apeldoorn', 'hospitality,receptie,gastvrijheid,talen', 'Bas Hendriks', 'bas.hendriks@veluwevakantieparken.example', '2026-08-20 02:00:00'),
(63, 16, 'Medewerker Housekeeping', 'Je maakt kamers en accommodaties schoon en zorgt dat alles tot in de puntjes verzorgd is voor nieuwe gasten. Bij Veluwe Vakantieparken werk je in een hecht team met flexibele uren.\n\nWij bieden een jaarcontract met uitzicht op vast, een eindejaarsuitkering en een fijn team.', 'Epe', 'schoonmaak,housekeeping,hotel,parttime', 'Bas Hendriks', 'bas.hendriks@veluwevakantieparken.example', '2026-08-18 13:00:00'),
(64, 16, 'Medewerker Groenvoorziening', 'Je onderhoudt parken, bermen en terreinen: maaien, snoeien en onkruid bestrijden. Je werkt met professioneel materieel van Veluwe Vakantieparken. Een trekkerrijbewijs is een pré.\n\nWij bieden een parttime of fulltime dienstverband, een fiets van de zaak en gezellige teamuitjes.', 'Apeldoorn', 'groen,onderhoud,buitenwerk,maaien', 'Bas Hendriks', 'bas.hendriks@veluwevakantieparken.example', '2026-08-17 00:00:00'),
(65, 17, 'Leerkracht Basisonderwijs', 'Je geeft les aan een groep in het basisonderwijs en zorgt dat iedere leerling zich optimaal ontwikkelt. Binnen Kompas Onderwijsgroep werk je samen met betrokken collega''s aan modern en uitdagend onderwijs.\n\nWij bieden een salaris conform cao, 25 vakantiedagen en een goede pensioenregeling.', 'Amersfoort', 'onderwijs,basisschool,pabo,kinderen', 'Esther Mulder', 'esther.mulder@kompasonderwijsgroep.example', '2026-08-15 11:00:00'),
(66, 17, 'Docent Informatica', 'Je geeft les in programmeren, databases en netwerken aan mbo-studenten. Je ontwikkelt lesmateriaal en begeleidt studenten tijdens hun stage. Kompas Onderwijsgroep zoekt iemand met praktijkervaring in de ICT.\n\nWij bieden een marktconform salaris, een reiskostenvergoeding en ruimte voor opleidingen.', 'Amersfoort', 'onderwijs,informatica,ict,docent,programmeren', 'Esther Mulder', 'esther.mulder@kompasonderwijsgroep.example', '2026-08-13 22:00:00'),
(67, 17, 'Onderwijsassistent', 'Je ondersteunt leerkrachten in de klas en begeleidt kleine groepjes leerlingen met extra instructie. Je bent een onmisbare schakel binnen de scholen van Kompas Onderwijsgroep.\n\nWij bieden een contract voor 32 tot 40 uur, flexibele werktijden en een informele werksfeer.', 'Soest', 'onderwijs,ondersteuning,kinderen,mbo', 'Esther Mulder', 'esther.mulder@kompasonderwijsgroep.example', '2026-08-12 09:00:00'),
(68, 17, 'HR Adviseur', 'Je adviseert leidinggevenden over personeelszaken zoals verzuim, ontwikkeling en arbeidsrecht. Je denkt mee over het HR-beleid van Kompas Onderwijsgroep en voert het uit. Je hebt een hbo-opleiding in HR.\n\nWij bieden een jaarcontract met uitzicht op vast, een eindejaarsuitkering en een fijn team.', 'Amersfoort', 'hr,personeelszaken,advies,verzuim', 'Esther Mulder', 'esther.mulder@kompasonderwijsgroep.example', '2026-08-10 20:00:00'),
(69, 18, 'Automonteur', 'Je voert onderhoud, reparaties en APK-keuringen uit aan personenauto''s. Je werkt met moderne diagnoseapparatuur in de werkplaats van Van Loon Autogroep. Een mbo-diploma Autotechniek is gewenst.\n\nWij bieden een parttime of fulltime dienstverband, een fiets van de zaak en gezellige teamuitjes.', 'Breda', 'auto,monteur,apk,techniek', 'Erik van Loon', 'erik.vanloon@vanloonautogroep.example', '2026-08-09 07:00:00'),
(70, 18, 'Autoverkoper', 'Je adviseert klanten bij de aankoop van een nieuwe of gebruikte auto, maakt proefritten en sluit deals. Bij Van Loon Autogroep krijg je een aantrekkelijke bonusregeling en een auto van de zaak.\n\nWij bieden een salaris conform cao, 25 vakantiedagen en een goede pensioenregeling.', 'Roosendaal', 'sales,auto,verkoop,klantcontact', 'Erik van Loon', 'erik.vanloon@vanloonautogroep.example', '2026-08-07 18:00:00'),
(71, 18, 'Schadehersteller', 'Je herstelt plaatwerk- en lakschade aan voertuigen tot in de perfectie. Je werkt in een moderne spuiterij van Van Loon Autogroep. Ervaring met uitdeuken en spuiten is een pré.\n\nWij bieden een marktconform salaris, een reiskostenvergoeding en ruimte voor opleidingen.', 'Breda', 'auto,schadeherstel,spuiten,plaatwerk', 'Erik van Loon', 'erik.vanloon@vanloonautogroep.example', '2026-08-06 05:00:00'),
(72, 18, 'Serviceadviseur', 'Je ontvangt klanten aan de servicebalie, plant werkplaatsafspraken en licht uitgevoerde werkzaamheden toe. Je bent de schakel tussen klant en monteurs van Van Loon Autogroep.\n\nWij bieden een contract voor 32 tot 40 uur, flexibele werktijden en een informele werksfeer.', 'Breda', 'auto,klantcontact,werkplaats,planning', 'Erik van Loon', 'erik.vanloon@vanloonautogroep.example', '2026-08-04 16:00:00'),
(73, 19, 'Laboratorium Analist', 'Je voert chemische analyses uit op grondstoffen en eindproducten met technieken zoals HPLC en GC. Je documenteert resultaten volgens GMP-richtlijnen van Delta Farma Lab. Je hebt een mbo- of hbo-opleiding Chemie.\n\nWij bieden een jaarcontract met uitzicht op vast, een eindejaarsuitkering en een fijn team.', 'Leiden', 'laboratorium,analyse,chemie,hplc', 'Nadia Visser', 'nadia.visser@deltafarmalab.example', '2026-08-03 03:00:00'),
(74, 19, 'QA Officer', 'Je bewaakt de kwaliteitssystemen en zorgt dat processen voldoen aan GMP-richtlijnen. Je beoordeelt afwijkingen, begeleidt audits en schrijft procedures voor Delta Farma Lab.\n\nWij bieden een parttime of fulltime dienstverband, een fiets van de zaak en gezellige teamuitjes.', 'Leiden', 'kwaliteit,gmp,farma,documentatie', 'Nadia Visser', 'nadia.visser@deltafarmalab.example', '2026-08-01 14:00:00'),
(75, 19, 'Regulatory Affairs Specialist', 'Je stelt registratiedossiers op voor geneesmiddelen en onderhoudt contact met autoriteiten zoals het CBG en EMA. Je volgt wet- en regelgeving op de voet voor Delta Farma Lab.\n\nWij bieden een salaris conform cao, 25 vakantiedagen en een goede pensioenregeling.', 'Leiden', 'farma,regelgeving,registratie,documentatie', 'Nadia Visser', 'nadia.visser@deltafarmalab.example', '2026-07-31 01:00:00'),
(76, 19, 'Productiemedewerker Farma', 'Je werkt in een cleanroom aan de productie van geneesmiddelen. Je volgt nauwkeurig de procedures en documenteert je werk volgens GMP bij Delta Farma Lab. Ervaring in een productieomgeving is een pré.\n\nWij bieden een marktconform salaris, een reiskostenvergoeding en ruimte voor opleidingen.', 'Leiden', 'farma,productie,gmp,cleanroom', 'Nadia Visser', 'nadia.visser@deltafarmalab.example', '2026-07-29 12:00:00'),
(77, 20, 'Installatiemonteur W', 'Je installeert sanitair, verwarming en warmtepompen bij particulieren en bedrijven. Je werkt zelfstandig of in een klein team van Stroomlijn Installatietechniek en zorgt dat de klant tevreden achterblijft.\n\nWij bieden een contract voor 32 tot 40 uur, flexibele werktijden en een informele werksfeer.', 'Tilburg', 'installatietechniek,loodgieter,warmtepompen,monteur', 'Mark van den Berg', 'mark.vandenberg@stroomlijninstallatietechniek.example', '2026-07-27 23:00:00'),
(78, 20, 'Servicemonteur CV', 'Je onderhoudt en repareert cv-ketels en klimaatinstallaties bij klanten thuis. Met je servicebus van Stroomlijn Installatietechniek ben je dagelijks onderweg. Je draait mee in de storingsdienst en bent klantvriendelijk.\n\nWij bieden een jaarcontract met uitzicht op vast, een eindejaarsuitkering en een fijn team.', 'Tilburg', 'cv,onderhoud,installatie,monteur,storingsdienst', 'Mark van den Berg', 'mark.vandenberg@stroomlijninstallatietechniek.example', '2026-09-24 10:00:00'),
(79, 20, 'Elektromonteur', 'Je legt elektrische installaties aan in woningen en bedrijfspanden en voert onderhoud en storingsdiensten uit. Bij Stroomlijn Installatietechniek werk je met moderne technieken zoals domotica en laadpalen. Een mbo-diploma Elektrotechniek is gewenst.\n\nWij bieden een parttime of fulltime dienstverband, een fiets van de zaak en gezellige teamuitjes.', 'Waalwijk', 'elektrotechniek,installatie,monteur,mbo', 'Mark van den Berg', 'mark.vandenberg@stroomlijninstallatietechniek.example', '2026-09-22 21:00:00'),
(80, 20, 'Werkvoorbereider', 'Je bereidt projecten voor: je maakt tekeningen, bestelt materialen en stelt planningen op. Zo zorg je dat de monteurs en bouwers van Stroomlijn Installatietechniek zonder vertraging aan de slag kunnen. Je bent nauwkeurig en communicatief sterk.\n\nWij bieden een salaris conform cao, 25 vakantiedagen en een goede pensioenregeling.', 'Tilburg', 'werkvoorbereiding,calculatie,projecten,installatie', 'Mark van den Berg', 'mark.vandenberg@stroomlijninstallatietechniek.example', '2026-09-21 08:00:00'),
(81, 21, 'Makelaar Wonen', 'Je begeleidt klanten bij de aan- en verkoop van woningen, van waardebepaling tot sleuteloverdracht. Je bent onderhandelingssterk en kent de lokale woningmarkt. Huisje Boompje Makelaars is aangesloten bij de NVM.\n\nWij bieden een marktconform salaris, een reiskostenvergoeding en ruimte voor opleidingen.', '''s-Hertogenbosch', 'vastgoed,makelaardij,verkoop,nvm', 'Claire Peters', 'claire.peters@huisjeboompjemakelaars.example', '2026-09-19 19:00:00'),
(82, 21, 'Commercieel Binnendienst Medewerker', 'Je plant bezichtigingen, verwerkt biedingen en houdt de administratie van woningdossiers bij. Je bent het eerste aanspreekpunt voor klanten die Huisje Boompje Makelaars bellen of mailen.\n\nWij bieden een contract voor 32 tot 40 uur, flexibele werktijden en een informele werksfeer.', '''s-Hertogenbosch', 'vastgoed,binnendienst,administratie,klantcontact', 'Claire Peters', 'claire.peters@huisjeboompjemakelaars.example', '2026-09-18 06:00:00'),
(83, 21, 'Taxateur', 'Je voert taxaties uit van woningen en bedrijfspanden voor hypotheekverstrekkers en particulieren. Je bent ingeschreven in het NRVT-register en werkt zelfstandig binnen Huisje Boompje Makelaars.\n\nWij bieden een jaarcontract met uitzicht op vast, een eindejaarsuitkering en een fijn team.', '''s-Hertogenbosch', 'vastgoed,taxaties,rmt,waardebepaling', 'Claire Peters', 'claire.peters@huisjeboompjemakelaars.example', '2026-09-16 17:00:00'),
(84, 21, 'Online Marketeer', 'Je bedenkt en voert online campagnes uit via SEO, SEA en social media. Met data uit analytics optimaliseer je de resultaten continu. Bij Huisje Boompje Makelaars krijg je de ruimte om te experimenteren.\n\nWij bieden een parttime of fulltime dienstverband, een fiets van de zaak en gezellige teamuitjes.', '''s-Hertogenbosch', 'marketing,seo,sea,social-media,analytics', 'Claire Peters', 'claire.peters@huisjeboompjemakelaars.example', '2026-09-15 04:00:00'),
(85, 22, 'Verkoopmedewerker', 'Je helpt klanten in de winkel, geeft advies en rekent af aan de kassa. Je zorgt dat de winkel van Lindeboom Retail er altijd verzorgd uitziet. Je bent klantvriendelijk en flexibel inzetbaar.\n\nWij bieden een salaris conform cao, 25 vakantiedagen en een goede pensioenregeling.', 'Venlo', 'retail,verkoop,klantcontact,winkel', 'Luc Janssen', 'luc.janssen@lindeboomretail.example', '2026-09-13 15:00:00'),
(86, 22, 'Filiaalmanager', 'Je bent eindverantwoordelijk voor het filiaal: omzet, personeel en presentatie. Je motiveert je team en zorgt voor een uitstekende klantbeleving bij Lindeboom Retail. Ervaring als leidinggevende in retail is vereist.\n\nWij bieden een marktconform salaris, een reiskostenvergoeding en ruimte voor opleidingen.', 'Maastricht', 'retail,leidinggeven,management,winkel', 'Luc Janssen', 'luc.janssen@lindeboomretail.example', '2026-09-12 02:00:00'),
(87, 22, 'Visual Merchandiser', 'Je zorgt voor aantrekkelijke etalages en winkelpresentaties die de verkoop stimuleren. Je bezoekt verschillende filialen van Lindeboom Retail en werkt nauw samen met de filiaalmanagers.\n\nWij bieden een contract voor 32 tot 40 uur, flexibele werktijden en een informele werksfeer.', 'Maastricht', 'retail,styling,presentatie,creatief', 'Luc Janssen', 'luc.janssen@lindeboomretail.example', '2026-09-10 13:00:00'),
(88, 22, 'Medewerker Vulploeg', 'Je vult de schappen, verwerkt leveringen en zorgt dat de winkel er de volgende ochtend weer netjes bij ligt. Een ideale bijbaan naast je studie bij Lindeboom Retail.\n\nWij bieden een jaarcontract met uitzicht op vast, een eindejaarsuitkering en een fijn team.', 'Heerlen', 'retail,vakkenvullen,bijbaan,avonddienst', 'Luc Janssen', 'luc.janssen@lindeboomretail.example', '2026-09-09 00:00:00'),
(89, 23, 'Redacteur', 'Je schrijft en redigeert artikelen voor onze tijdschriften en websites. Je hebt een scherpe pen, oog voor detail en een goede neus voor nieuws. Bij Polderpost Uitgeverij werk je samen met freelancers en vormgevers.\n\nWij bieden een parttime of fulltime dienstverband, een fiets van de zaak en gezellige teamuitjes.', 'Delft', 'redactie,schrijven,journalistiek,media', 'Joris de Boer', 'joris.deboer@polderpostuitgeverij.example', '2026-09-07 11:00:00'),
(90, 23, 'Grafisch Vormgever', 'Je ontwerpt huisstijlen, advertenties en publicaties, zowel voor print als online. Je werkt met Adobe InDesign, Illustrator en Photoshop en brengt de visuele identiteit van Polderpost Uitgeverij en haar klanten tot leven.\n\nWij bieden een salaris conform cao, 25 vakantiedagen en een goede pensioenregeling.', 'Delft', 'vormgeving,design,adobe,creatief,drukwerk', 'Joris de Boer', 'joris.deboer@polderpostuitgeverij.example', '2026-09-05 22:00:00'),
(91, 23, 'Accountmanager', 'Je onderhoudt en versterkt de relatie met bestaande klanten en zoekt actief naar nieuwe kansen. Je bent het gezicht van Polderpost Uitgeverij en weet klantwensen te vertalen naar passende oplossingen.\n\nWij bieden een marktconform salaris, een reiskostenvergoeding en ruimte voor opleidingen.', 'Delft', 'sales,accountmanagement,commercieel,b2b', 'Joris de Boer', 'joris.deboer@polderpostuitgeverij.example', '2026-09-04 09:00:00'),
(92, 23, 'Content Creator', 'Je maakt pakkende content voor social media en websites: video, fotografie en korte teksten. Je volgt trends op de voet en weet wat werkt bij de doelgroep van Polderpost Uitgeverij.\n\nWij bieden een contract voor 32 tot 40 uur, flexibele werktijden en een informele werksfeer.', 'Delft', 'content,video,social-media,marketing,creatief', 'Joris de Boer', 'joris.deboer@polderpostuitgeverij.example', '2026-09-02 20:00:00'),
(93, 24, 'Security Analist', 'In ons Security Operations Center monitor je netwerkverkeer en analyseer je security-incidenten. Je onderzoekt afwijkingen, adviseert over maatregelen en helpt klanten van SecureGrid Security weerbaarder te worden tegen aanvallen.\n\nWij bieden een jaarcontract met uitzicht op vast, een eindejaarsuitkering en een fijn team.', 'Den Haag', 'security,soc,monitoring,netwerk,ict', 'Laura Kramer', 'laura.kramer@securegridsecurity.example', '2026-09-01 07:00:00'),
(94, 24, 'Ethical Hacker', 'Als Ethical Hacker voer je penetratietesten uit op webapplicaties en netwerken van klanten. Je rapporteert kwetsbaarheden helder en geeft concreet advies. Bij SecureGrid Security krijg je ruimte voor certificeringen zoals OSCP.\n\nWij bieden een parttime of fulltime dienstverband, een fiets van de zaak en gezellige teamuitjes.', 'Den Haag', 'security,pentesting,hacking,webapplicaties', 'Laura Kramer', 'laura.kramer@securegridsecurity.example', '2026-08-30 18:00:00'),
(95, 24, 'Systeembeheerder', 'Als Systeembeheerder ben je verantwoordelijk voor servers, netwerken en werkplekken. Je lost storingen op, voert updates door en adviseert over verbeteringen in de IT-omgeving van SecureGrid Security. Je hebt kennis van zowel Linux als Windows.\n\nWij bieden een salaris conform cao, 25 vakantiedagen en een goede pensioenregeling.', 'Den Haag', 'systeembeheer,linux,windows,netwerk,ict', 'Laura Kramer', 'laura.kramer@securegridsecurity.example', '2026-08-29 05:00:00'),
(96, 24, 'Data Analist', 'Je verzamelt, analyseert en visualiseert data om betere beslissingen mogelijk te maken. Met SQL en Python bouw je rapportages en dashboards voor de teams van SecureGrid Security. Je kunt complexe inzichten helder uitleggen.\n\nWij bieden een marktconform salaris, een reiskostenvergoeding en ruimte voor opleidingen.', 'Den Haag', 'data,sql,python,analyse,rapportage', 'Laura Kramer', 'laura.kramer@securegridsecurity.example', '2026-08-27 16:00:00'),
(97, 25, 'Wijkverpleegkundige', 'Als Wijkverpleegkundige indiceer en coördineer je de zorg voor cliënten in de wijk. Je werkt zelfstandig, onderhoudt contact met huisartsen en coacht collega''s van Wijkzorg Twente. Je hebt een hbo-diploma Verpleegkunde.\n\nWij bieden een contract voor 32 tot 40 uur, flexibele werktijden en een informele werksfeer.', 'Enschede', 'zorg,wijkverpleging,thuiszorg,hbo', 'Wendy Bosch', 'wendy.bosch@wijkzorgtwente.example', '2026-08-26 03:00:00'),
(98, 25, 'Verzorgende IG', 'Je ondersteunt cliënten bij hun dagelijkse verzorging en voert voorbehouden handelingen uit. Bij Wijkzorg Twente staat persoonlijke aandacht centraal. Je hebt een diploma Verzorgende IG en werkt graag in een hecht team.\n\nWij bieden een jaarcontract met uitzicht op vast, een eindejaarsuitkering en een fijn team.', 'Almelo', 'zorg,verzorging,ouderenzorg,mbo', 'Wendy Bosch', 'wendy.bosch@wijkzorgtwente.example', '2026-08-24 14:00:00'),
(99, 25, 'Helpende Zorg & Welzijn', 'Je helpt cliënten met huishoudelijke taken, maaltijden en dagbesteding. Je zorgt voor een prettige en veilige leefomgeving en signaleert veranderingen bij cliënten van Wijkzorg Twente. Een mbo-diploma niveau 2 is gewenst.\n\nWij bieden een parttime of fulltime dienstverband, een fiets van de zaak en gezellige teamuitjes.', 'Hengelo', 'zorg,welzijn,ouderenzorg,mbo', 'Wendy Bosch', 'wendy.bosch@wijkzorgtwente.example', '2026-08-23 01:00:00'),
(100, 25, 'Recruiter', 'Je vindt en werft nieuwe collega''s voor Wijkzorg Twente. Je schrijft vacatureteksten, benadert kandidaten actief en voert selectiegesprekken. Je kent de arbeidsmarkt en bent een echte netwerker.\n\nWij bieden een salaris conform cao, 25 vakantiedagen en een goede pensioenregeling.', 'Hengelo', 'recruitment,hr,werving,arbeidsmarkt', 'Wendy Bosch', 'wendy.bosch@wijkzorgtwente.example', '2026-08-21 12:00:00');
